import sys

def counting_sort(arr, exp):
    n = len(arr)
    output = [0] * n
    count = [0] * 10

    for i in range(n):
        index = (abs(arr[i]) // exp) % 10
        count[index] += 1

    for i in range(1, 10):
        count[i] += count[i - 1]

    for i in range(n - 1, -1, -1):
        index = (abs(arr[i]) // exp) % 10
        output[count[index] - 1] = arr[i]
        count[index] -= 1

    for i in range(n):
        arr[i] = output[i]

def radix_sort(arr):
    if not arr:
        return arr

    neg = [x for x in arr if x < 0]
    pos = [x for x in arr if x >= 0]

    if neg:
        neg = [-x for x in neg]
        radix_sort_positive(neg)
        neg = [-x for x in neg[::-1]]

    if pos:
        radix_sort_positive(pos)

    return neg + pos

def radix_sort_positive(arr):
    if not arr:
        return

    max_val = max(arr)
    exp = 1

    while max_val // exp > 0:
        counting_sort(arr, exp)
        exp *= 10

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    if n == 0:
        print()
        return

    arr = list(map(int, data[1:n+1]))
    result = radix_sort(arr)
